<div class="page-heading"><div><span class="eyebrow">Competencia y participación</span><h1>Programa de capacitaciones</h1><p>Formación dirigida a los peligros prioritarios y a todos los niveles de la organización.</p></div><a href="#nueva-capacitacion" class="btn-primary"><?= icon('plus', 'h-4 w-4') ?> Programar capacitación</a></div>
<?php $total = count($trainings); $done = count(array_filter($trainings, fn($item) => $item['estado'] === 'Realizada')); $hours = array_sum(array_map(fn($item) => (float) $item['duracion_horas'], $trainings)); ?>
<section class="mt-6 grid grid-cols-3 gap-3"><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Programadas / total</p><p class="mt-2 text-2xl font-semibold"><?= $total - $done ?> <span class="text-sm text-slate-400">/ <?= $total ?></span></p></div><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Realizadas</p><p class="mt-2 text-2xl font-semibold text-emerald-600"><?= $done ?></p></div><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Horas planificadas</p><p class="mt-2 text-2xl font-semibold"><?= e($hours) ?></p></div></section>
<section class="ios-card mt-6 overflow-hidden"><div class="card-heading"><div><h2>Cronograma de formación</h2><p>Gestiona participantes, asistencia, evaluación y eficacia en cada capacitación.</p></div></div><?php if ($trainings === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('cap', 'h-7 w-7') ?></span><h3>No hay capacitaciones</h3><p>Programa la primera actividad de formación.</p></div><?php else: ?><div class="divide-y divide-slate-100"><?php foreach ($trainings as $training): ?><article class="grid gap-4 p-5 sm:grid-cols-[90px_1fr_auto] sm:p-6"><div class="date-tile !h-[68px] !w-[68px]<?= is_overdue($training) ? ' is-overdue' : '' ?>"><strong class="!text-xl"><?= date('d', strtotime($training['fecha_programada'])) ?></strong><span><?= ['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'][(int) date('n', strtotime($training['fecha_programada'])) - 1] ?></span></div><div><div class="flex flex-wrap items-center gap-2"><span class="badge badge-blue"><?= e($training['modalidad']) ?></span><span class="badge <?= status_class($training['estado']) ?>"><?= e($training['estado']) ?></span><?php if (is_overdue($training)): ?><span class="badge badge-red">Fecha vencida</span><?php endif; ?></div><h3 class="mt-2.5 text-sm font-semibold leading-5 text-slate-800"><?= e($training['tema']) ?></h3><p class="mt-1.5 max-w-3xl text-xs leading-5 text-slate-500"><?= e($training['descripcion']) ?></p><p class="mt-2 text-[11px] text-slate-400"><?= e($training['responsable']) ?> · <?= e($training['duracion_horas']) ?> horas · <?= format_date($training['fecha_programada'], true) ?></p></div><div class="min-w-[200px] sm:self-center"><div class="mb-3 flex flex-wrap gap-3"><a href="<?= e(url('/capacitaciones/' . $training['id'])) ?>" class="inline-flex items-center gap-1 text-[11px] font-medium text-blue-600 hover:underline"><?= icon('users', 'h-3.5 w-3.5') ?> Asistencia</a><a href="<?= e(url('/evidencias?vinculo=' . rawurlencode('capacitacion:' . $training['id']) . '#cargar')) ?>" class="inline-flex items-center gap-1 text-[11px] font-medium text-blue-600 hover:underline"><?= icon('upload', 'h-3.5 w-3.5') ?> Evidencias</a><a href="<?= e(url('/capacitaciones/' . $training['id'] . '/editar')) ?>" class="inline-flex items-center gap-1 text-[11px] font-medium text-blue-600 hover:underline"><?= icon('edit', 'h-3.5 w-3.5') ?> Editar</a><form method="post" action="<?= e(url('/capacitaciones/' . $training['id'] . '/eliminar')) ?>" data-confirm="¿Eliminar esta capacitación del cronograma? Conserva por separado cualquier evidencia de formación ya realizada."><?= csrf_field() ?><button type="submit" class="inline-flex items-center gap-1 text-[11px] font-medium text-rose-600 hover:underline"><?= icon('x', 'h-3.5 w-3.5') ?> Eliminar</button></form></div><form method="post" action="<?= e(url('/capacitaciones/' . $training['id'] . '/estado')) ?>" class="flex gap-2"><?= csrf_field() ?><select name="estado" class="input h-9 !w-auto flex-1 text-xs"><?php foreach (['Programada','Realizada','Cancelada'] as $state): ?><option<?= selected($training['estado'], $state) ?>><?= $state ?></option><?php endforeach; ?></select><button class="btn-secondary h-9 px-3" type="submit">Guardar</button></form></div></article><?php endforeach; ?></div><?php endif; ?></section>
