step="0.5" class="input" value="<?= e(old('duracion_horas', 1)) ?>" required></div><div><label class="label">Modalidad *</label><select name="modalidad" class="input"><?php foreach (['Presencial','Virtual','Mixta'] as $mode): ?><option<?= selected(old('modalidad'), $mode) ?>><?= $mode ?></option><?php endforeach; ?></select></div><div class="sm:col-span-2 flex justify-end"><button class="btn-primary" type="submit">Programar capacitación</button></div></form></details>
